ANNOTATIONS = [
    (37, 'after', r'''RESPONSE_TIMEOUT_MS = 60s：POST 之后 60 秒没有任何消息到达就认为会话卡死，插警告 + 重连 WS。'''),
    (41, 'after', r'''compaction 期间拉长到 180s：compact API 调用本身要 5-30s，且会阻塞其他 SDK 消息——贴着 60s 边缘跑 compact 会被误判成卡死。'''),
    (55, 'after', r'''Props 面：远端会话管理器配置、消息/加载态的 setter、init 回调（拿远端可用的 slash 命令）、权限队列 setter，以及三个可选的流式回调（非流式宿主不传）。'''),
    (76, 'before', r'''useRemoteSession：把 REPL 接到远端的 CCR 会话上。四条通道：WS 收 SDK 消息并转成 REPL 消息、HTTP POST 发用户输入、权限请求借道现有 ToolUseConfirm 队列、任务/工具进度靠桥 WS 上的系统消息推断。'''),
    (98, 'after', r'''连接状态写入带相等短路——WS 心跳里重复置同一个值不该产生新 state 对象。'''),
    (111, 'after', r'''runningTaskIdsRef 是事件源计数：viewer 自己的 AppState.tasks 是空的（任务跑在另一个进程里），task_started/task_notification 经桥 WS 到达，差值写进 remoteBackgroundTaskCount 供「N in background」角标显示。'''),
    (119, 'after', r'''isCompactingRef：compaction 期间 CLI worker 忙于 API 调用、短期内不会发消息——用更长超时并抑制「无响应」误报。'''),
    (137, 'after', r'''为什么是有界环形（50）而不是 delete-on-match：同一个 POST 可能回声多次——服务器直接广播到 /subscribe 一次，worker（cowork 桌面/CLI daemon）在写路径上再回声一次。delete-on-match 会漏放第二次。环形天然兜住重复，容量按「用户不可能比回声更快打 50 条」设定。注意它不处理 attach 时刻的历史-实时重叠（没有东西用历史 UUID 播种，只有 sendMessage 往里加）。'''),
    (143, 'after', r'''toolsRef 让 WS 回调不读到陈旧工具表（权限请求查找 Tool 对象用）。'''),
    (154, 'after', r'''onMessage 的调试日志先拼 type/subtype/content 类型摘要——远端会话排障全靠这行，消息本体可能很大不能整个打。'''),
    (175, 'after', r'''清除超时必须排在回声过滤之前：我们自己 POST 的 WS 回声就是心跳——慢速流式的 agent（compaction、冷启动）靠它活着。放到过滤后面，这些会话会无端触发 60s 无响应警告 + 重连。'''),
    (191, 'after', r'''回声过滤命中即丢弃（本地 POST 前已经渲染过这条消息了），但**不删**记录——同一 uuid 会来第二次，环形的使命就是这个。'''),
    (202, 'after', r'''system/init 消息把远端可用的 slash 命令抽出来交给 onInit——本地斜杠菜单要与远端的实际能力对齐。'''),
    (221, 'after', r'''task_progress 是纯状态信号，没有可渲染内容，直接丢。'''),
    (235, 'after', r'''compaction 状态机：status=compacting 开始、compact_boundary 或 status=null 结束。重复的 compacting 是 keep-alive tick——只更新 ref 不进消息列表（否则用户每小时看到几十条「压缩中」）。'''),
    (242, 'after', r'''会话结束消息：停 loading。注意 assistant 消息**不**停 loading——agent 可能还在工具循环里，只有会话结束或权限请求才停。'''),
    (267, 'after', r'''清 in-progress tool_use ID 必须读**原始** sdkMessage：非 viewerOnly 模式下 convertSDKMessage 把 user 消息返 {type:'ignored'}，转换后再删就永远不触发。与下面的 add site 和 inProcessRunner.ts 三处镜像；不清的话集合整个会话周期无限增长（BQ 数据：CCR cohort 的 RSS 斜率高 5.2 倍）。'''),
    (278, 'after', r'''viewerOnly 模式的转换选项：远端 agent 跑 BriefTool（SendUserMessage），它的 tool_use 块 userFacingName() 是空串、渲染出来是空的，实际内容在 tool_result 里——所以必须开 convertToolResults + convertUserTextMessages 才能看到东西。'''),
    (305, 'after', r'''完整消息路径三件事：清空流式状态（完整消息取代部分流式状态）；assistant 消息把 tool_use 块标成 in-progress——本地会话这活由 toolOrchestration.ts 干，远端会话收到的是预制 assistant 消息、没有本地工具执行，UI 不补就是「Waiting…」；消息入列。'''),
    (327, 'after', r'''stream_event 路径交给 handleMessageFromStream 实时更新 UI。'ignored' 类型的消息静默丢弃。'''),
    (343, 'after', r'''createSyntheticAssistantMessage：远端的权限请求没有本地 assistant 消息可挂，造一条合成的，让 ToolUseConfirm 队列的渲染组件有东西可渲染。'''),
    (401, 'after', r'''ToolUseConfirm 四回调：abort/reject 都回 deny + 摘队列，allow 回 allow + 摘队列 + 恢复 loading（批准后远端继续跑）。onUserInteraction 和 recheckPermission 是 no-op——分类器跑在容器那头，本地没有可重查的状态。'''),
    (416, 'after', r'''远端取消权限请求（比如会话被 kill）：摘队列 + 恢复 loading，和本地拒绝一个效果。'''),
    (430, 'after', r'''重连间隙的两个清理都选「清零而不是漂移」：WS 断开期间可能漏收 task_notification，宁可少算几个后台任务，不让计数永远偏高；同理漏收的 tool_result 会留下永久转圈的 spinner。'''),
    (443, 'after', r'''RemoteSessionManager 的完整回调面：消息、权限请求/取消、连接状态四态、错误。'''),
    (457, 'after', r'''cleanup：清待决超时 + 断管理器。'''),
    (493, 'after', r'''POST **之前**记录 UUID：回声可能比 POST promise 先解析——后记就漏了过滤，用户看到自己刚打的消息出现两遍。'''),
    (501, 'after', r'''POST 失败也不用撤销预记的 UUID：环形的容量会自然淘汰它，为一次失败维护回退逻辑不划算。'''),
    (532, 'after', r'''无初始 prompt 的会话在第一条消息后补标题：给 claude.ai 上一个有意义的标题而不是「Background task」。viewerOnly 跳过——远端 agent 拥有会话标题。generateSessionTitle 内部永不 reject（body 包 try/catch，失败返 null），所以这条链不用挂 .catch。'''),
    (561, 'after', r'''卡死检测的装表：viewerOnly 跳过（远端可能 idle-shut，重启要 >60s）；compaction 中用长超时。触发时插一条 warning 系统消息 + manager.reconnect()——订阅可能已经陈旧了。'''),
    (583, 'after', r'''cancelRequest：清超时 + 发中断。viewerOnly 不中断远端——Ctrl+C 是本地取消，不该杀远程 agent。'''),
    (593, 'after', r'''disconnect：清超时 + 断管理器 + 清 ref（幂等，重复调用安全）。'''),
    (604, 'after', r'''返回值必须 useMemo：四个字段本身稳定，但新的对象字面量会让 REPL 的 onSubmit useCallback 每次渲染都失效，进而churn PromptInput 的 props 和下游所有 memo。'''),
]
